(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = { steps: [] };
  try {
    // ① 登录 + 找到刚才那个卍解项目
    const res = await fetch('/api/auth/demo', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const data = await res.json();
    localStorage.setItem('token', data.token);
    localStorage.setItem('user', JSON.stringify(data.user));

    const list = await fetch('/api/projects', { headers: { Authorization: 'Bearer ' + data.token } }).then((r) => r.json());
    const mine = (list.projects || []).find((p) => p.name && p.name.includes('服务器版测试'));
    out.foundProject = !!mine;
    out.projectDifficulty = mine?.difficulty || null;
    if (!mine) return JSON.stringify(out);

    // ② 打开项目详情（客户端跳转）
    [...document.querySelectorAll('header a')].find((a) => a.textContent.trim() === '项目')?.click();
    await sleep(3000);
    const link = [...document.querySelectorAll('a')].find((a) => a.href && a.href.includes(`/projects/${mine.id}`));
    link?.click();
    for (let i = 0; i < 16; i++) { await sleep(500); if (document.querySelector('.pc-wrap')) break; }
    out.opened = document.querySelector('.pj-title')?.textContent || null;
    out.codePanel = !!document.querySelector('.pc-wrap');

    // ③ 贴一段代码（含中文注释）
    [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
    await sleep(700);
    const inputs = [...document.querySelectorAll('.pc-input')];
    out.inputCount = inputs.length;
    setV(inputs[0], 'server_test.c');
    setV(inputs[1], '服务器版测试用');
    setV(document.querySelector('.pc-textarea'), '#include <stdio.h>\n// 服务器版：中文注释也要能存\nint main(void) { return 0; }\n');
    [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
    await sleep(2500);
    out.codeName = document.querySelector('.pc-item-name')?.textContent || null;

    // ④ 接线表一行
    [...document.querySelectorAll('.pc-tab')].find((b) => b.textContent.includes('接线表'))?.click();
    await sleep(700);
    const pinInputs = [...document.querySelectorAll('.pc-inline-form .pc-input')];
    setV(pinInputs[0], '超声波 HC-SR04');
    setV(pinInputs[1], 'TRIG');
    setV(pinInputs[2], 'PA0');
    setV(pinInputs[3], '服务器版测试');
    [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('加一行'))?.click();
    await sleep(2200);
    out.pinRows = document.querySelectorAll('.pc-table tbody tr').length;

    // ⑤ 调试记录一条
    [...document.querySelectorAll('.pc-tab')].find((b) => b.textContent.includes('调试记录'))?.click();
    await sleep(700);
    setV(document.querySelector('.pc-input-full'), '服务器上中文乱码');
    setV(document.querySelector('.pc-textarea-sm'), '数据库和页面都要用 UTF-8，这里已经统一');
    [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('记下来'))?.click();
    await sleep(2200);
    out.debugs = document.querySelectorAll('.pc-debug').length;

    // ⑥ 开发环境
    [...document.querySelectorAll('.pc-tab')].find((b) => b.textContent.includes('开发环境'))?.click();
    await sleep(700);
    setV(document.querySelector('.pc-textarea'), 'gcc 13 + make（服务器版测试）');
    [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.trim() === '保存')?.click();
    await sleep(2000);
    out.envMsg = document.querySelector('.pc-msg')?.textContent || null;

    // ⑦ 直接问接口：数据真的在服务器上吗
    const detail = await fetch(`/api/projects/${mine.id}`, { headers: { Authorization: 'Bearer ' + data.token } }).then((r) => r.json());
    out.server = {
      difficulty: detail.project?.difficulty,
      codeNote: (detail.project?.code_note || '').slice(0, 24),
      code: (detail.codeFiles || []).map((c) => ({ name: c.name, chars: (c.content || '').length, cn: (c.content || '').includes('中文注释') })),
      pins: (detail.pinRows || []).map((r) => `${r.module}/${r.pin}→${r.board_pin}`),
      debugs: (detail.debugNotes || []).map((d) => d.problem),
    };
  } catch (e) {
    out.error = String(e && e.message ? e.message : e);
  }
  return JSON.stringify(out);
})()
